// DFS to build a chain
function buildChain(start: number, prevIdx: number | null, chain: Segment[]): boolean {
    const seg = segments[start];
    visited.add(start);
    chain.push(seg);
    const coordKey = (p: Point) => `${p.x.toFixed(3)},${p.y.toFixed(3)}`;
    const prevKey = prevIdx !== null ? coordKey(segments[prevIdx].p2) : '';
    const startKey = coordKey(seg.p1);
    const endKey = coordKey(seg.p2);
    let nextIdx: number | null = null;
    const connectedIdxs = adjacency.get(endKey)!;
    for(const idx of connectedIdxs){
        if(visited.has(idx)) continue;
        if(prevIdx !== null && idx === prevIdx) continue;
        const nextSeg = segments[idx];
        const nextKey = coordKey(nextSeg.p1);
        if(nextKey === startKey){
            nextIdx = idx;
            break;
        }
    }
    if(nextIdx === null) return false;
    return buildChain(nextIdx, start, chain);
}

